@php $pendingDeposits=\Illuminate\Support\Facades\DB::table('member_deposit_requests')->where('status','pending')->count(); $lastPendingDeposit=(int)\Illuminate\Support\Facades\DB::table('member_deposit_requests')->where('status','pending')->max('id'); @endphp
<aside id="pending-deposit-notice" style="position:fixed;bottom:16px;right:16px;z-index:9998;padding:12px 16px;background:#173354;color:#fff;border:1px solid #d2a64f;border-radius:12px;max-width:calc(100vw - 40px);font:14px system-ui"><a href="{{ route('admin.deposit-review.index') }}" style="color:#fff">🔔 Pending deposits: <strong id="pending-deposit-count">{{ $pendingDeposits }}</strong> — Review</a><span id="pending-deposit-new" role="status"></span></aside>
<script>(()=>{let count={{ (int)$pendingDeposits }},last={{ $lastPendingDeposit }};setInterval(async()=>{if(document.visibilityState!=='visible')return;try{const r=await fetch({{ Illuminate\Support\Js::from(route('admin.deposit-notifications')) }},{headers:{Accept:'application/json'}});if(!r.ok)return;const d=await r.json();document.getElementById('pending-deposit-count').textContent=d.pending;if(d.pending>count||d.last_id>last)document.getElementById('pending-deposit-new').textContent=' · नई deposit request आई है';count=d.pending;last=d.last_id;}catch(e){}},30000);})();</script>
